// AMyGameMode.h
#include "CoreTypes.h"
#include "Game Modes/AMyGameMode.h"
#include "AudioSubsystem.h"

protected:
    UFIELD(FString, DefaultMicBusName, TEXT("MicInputBus"), MODIFY_CONST, EDIT_DEFAULTPROP);

// AMyGameMode.cpp
IMPLEMENT_GAME_MODE_AMY

void AMyGameMode::BeginPlay(const EGenPhase Phase)
{
    Super::BeginPlay(Phase);

    UAudioSubsystem* Subsys = World->GetSubsystem<UAudioSubsystem>();
    if (!Subsys) {
        FMessageUtils::Error(TEXT("Audio subsystem not found!"));
        return;
    }

    // Get the audio device (usually initialized early)
    auto* Device = Subsys->GetDevice().Get();
    if (!Device) {
        FMessageUtils::Error(TEXT("Audio device not initialized!"));
        return;
    }

    // Find a microphone input device
    int32 MicIndex = -1;
    IInputDevice* Mic = nullptr;
    TArray<TSharedRef<InputDevice>> Inputs;
    Device->IterateInputDevices(Inputs);
    for (int i = 0; i < Inputs.Num(); i++) {
        FString Name = Inputs[i]->GetName();
        if (Name.Contains(TEXT("Micro"))) {
            Mic = Inputs[i].ToTempUniquePtr();
            MicIndex = Inputs[i]->GetIndex();
            break;
        }
    }
    if (MicIndex == -1) {
        FMessageUtils::Warn(TEXT("No microphone found. Mic audio will not be captured."));
        return;
    }

    // Get or create an output bus for the captured audio
    auto* Bus = World->GetBusByNameString(DefaultMicBusName);
    if (!Bus) {
        Bus = NewObject<UAudioBus>();
        Subsys->AddBus(Bus);
    }

    // Inject the mic into the bus (PassThrough means it just passes raw samples)
    if (Bus->AddInputDevice(MicIndex, EMixMode::PassThrough)) {
        FMessageUtils::Notice(TEXT("Microphone added to %s bus successfully.", *DefaultMicBusName));
    } else {
        FMessageUtils::Error(TEXT("Failed to add mic to bus."));
    }

    // Optional: Mute the mic on the default output bus if you don't want it in ambient yet
